function settings_ck($s,$k){return (($s[$k]??'0')==='1')?'checked':'';}
function settings_num($value,$min,$max,$fallback){$v=is_numeric($value)?(int)$value:$fallback;return max($min,min($max,$v));}
function settings_float($value,$min,$max){if($value===''||$value===null)return null;if(!is_numeric($value))return false;$v=(float)$value;return ($v<$min||$v>$max)?false:$v;}
function settings_branch_name($b){return (string)($b['code']??'BR').' · '.(string)($b['name']??'Branch');}
function settings_brand_media_dir(): string {return __DIR__.'/storage/customer-web-media/system-branding';}
function settings_brand_ensure_dir(): bool {$dir=settings_brand_media_dir();if(is_dir($dir)&&is_writable($dir))return true;if(!is_dir($dir)){@mkdir($dir,0775,true);clearstatcache(true,$dir);}if(is_dir($dir)&&!is_writable($dir)){@chmod($dir,0775);clearstatcache(true,$dir);}return is_dir($dir)&&is_writable($dir);}
function settings_brand_kind_key(string $kind): string {
 $map=['sidebar'=>'brand_sidebar_logo','favicon_customer'=>'brand_favicon_customer','favicon_admin'=>'brand_favicon_admin','favicon_checkin'=>'brand_favicon_checkin'];
 return (string)($map[$kind]??'');
}
function settings_brand_is_favicon(string $kind): bool {return strpos($kind,'favicon_')===0;}
function settings_brand_upload(string $field,string $kind): string {
 $f=$_FILES[$field]??null;if(!$f||($f['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE)throw new RuntimeException('กรุณาเลือกไฟล์ก่อนอัปโหลด');
 if(($f['error']??UPLOAD_ERR_OK)!==UPLOAD_ERR_OK)throw new RuntimeException('อัปโหลดไฟล์ไม่สำเร็จ (Upload error '.(int)($f['error']??-1).')');
 $isFavicon=settings_brand_is_favicon($kind);$limit=$isFavicon?2*1024*1024:5*1024*1024;if((int)($f['size']??0)<=0||(int)$f['size']>$limit)throw new RuntimeException($isFavicon?'Icon ต้องมีขนาดไม่เกิน 2MB':'Logo ต้องมีขนาดไม่เกิน 5MB');
 $fi=new finfo(FILEINFO_MIME_TYPE);$mime=(string)$fi->file((string)$f['tmp_name']);
 $allowed=$isFavicon?['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','image/x-icon'=>'ico','image/vnd.microsoft.icon'=>'ico']:['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];
 $ext=$allowed[$mime]??null;if(!$ext)throw new RuntimeException($isFavicon?'Favicon รองรับ JPG, PNG, WEBP หรือ ICO เท่านั้น':'Sidebar Logo รองรับ JPG, PNG หรือ WEBP เท่านั้น');
 if(!settings_brand_ensure_dir())throw new RuntimeException('Server ไม่อนุญาตให้เขียนโฟลเดอร์ Branding กรุณาตรวจ Permission ของ storage/customer-web-media');
 $prefix=$isFavicon?$kind:'sidebar-logo';$name=$prefix.'-'.date('YmdHis').'-'.bin2hex(random_bytes(4)).'.'.$ext;$dest=settings_brand_media_dir().'/'.$name;
 if(!move_uploaded_file((string)$f['tmp_name'],$dest))throw new RuntimeException('ไม่สามารถบันทึกไฟล์ Branding บน Server ได้');@chmod($dest,0664);
 return mr_branding_media_prefix().$name;
}
function settings_brand_valid_rel(string $rel,string $group=''): bool {
 if($rel===''||strpos(str_replace('\\\\','/',$rel),mr_branding_media_prefix())!==0)return false;
 $base=basename($rel);if(!preg_match('/^[A-Za-z0-9._-]+$/',$base))return false;
 if($group==='sidebar'&&strpos($base,'sidebar-logo-')!==0)return false;
 if($group==='favicon'&&strpos($base,'favicon')!==0)return false;
 $root=realpath(settings_brand_media_dir());$file=realpath(__DIR__.'/'.$rel);return (bool)($root&&$file&&is_file($file)&&strpos($file,$root.DIRECTORY_SEPARATOR)===0);
}
function settings_brand_gallery(string $group): array {
 $dir=settings_brand_media_dir();if(!is_dir($dir))return [];$rows=[];$files=@scandir($dir);if(!is_array($files))return [];
 foreach($files as $name){if($name==='.'||$name==='..'||!preg_match('/^[A-Za-z0-9._-]+$/',$name))continue;$rel=mr_branding_media_prefix().$name;if(!settings_brand_valid_rel($rel,$group))continue;$file=$dir.'/'.$name;$rows[]=['rel'=>$rel,'name'=>$name,'mtime'=>(int)@filemtime($file),'size'=>(int)@filesize($file),'url'=>'brand-media.php?file='.rawurlencode($name).'&v='.(int)@filemtime($file)];}
 usort($rows,function($a,$b){return ($b['mtime']??0)<=>($a['mtime']??0);});return array_slice($rows,0,100);
}

